import{c as a,Q as s,j as t,m as i}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse(`{"title":"Turn a Departing Engineer's Judgment Into an Editable, Versioned Skill File","description":"","frontmatter":{"url":"https://x.com/AlphaSignalAI/status/2061521674546119026","title":"Turn a Departing Engineer's Judgment Into an Editable, Versioned Skill File","author":"AlphaSignalAI","archived":"2026-06-02T00:00:00.000Z","handle":"@AlphaSignalAI","published":"2026-06-01T00:00:00.000Z","stats":"7 likes · 0 retweets · 16 bookmarks · 2543 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-01-@AlphaSignalAI-119026.md","filePath":"research/tweets/2026-06-01-@AlphaSignalAI-119026.md","lastUpdated":1780990164000}`),l={name:"research/tweets/2026-06-01-@AlphaSignalAI-119026.md"};function n(r,e,o,h,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="turn-a-departing-engineer-s-judgment-into-an-editable-versioned-skill-file-—-alphasignalai" tabindex="-1">Turn a Departing Engineer&#39;s Judgment Into an Editable, Versioned Skill File — @AlphaSignalAI <a class="header-anchor" href="#turn-a-departing-engineer-s-judgment-into-an-editable-versioned-skill-file-—-alphasignalai" aria-label="Permalink to &quot;Turn a Departing Engineer&#39;s Judgment Into an Editable, Versioned Skill File — @AlphaSignalAI&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/AlphaSignalAI/status/2061521674546119026" target="_blank" rel="noreferrer">https://x.com/AlphaSignalAI/status/2061521674546119026</a><strong>作者</strong>：AlphaSignalAI（@AlphaSignalAI） <strong>發布日期</strong>：2026-06-01 <strong>收錄日期</strong>：2026-06-02 <strong>類型</strong>：Twitter Article <strong>統計</strong>：7 likes · 0 retweets · 16 bookmarks · 2543 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><h2 id="colleague-skill-reframes-the-viral-dot-skill-repo-expertise-as-editable-versioned-files-not-a-clone" tabindex="-1">COLLEAGUE.SKILL reframes the viral dot-skill repo: expertise as editable, versioned files, not a clone. <a class="header-anchor" href="#colleague-skill-reframes-the-viral-dot-skill-repo-expertise-as-editable-versioned-files-not-a-clone" aria-label="Permalink to &quot;COLLEAGUE.SKILL reframes the viral dot-skill repo: expertise as editable, versioned files, not a clone.&quot;">​</a></h2><hr><blockquote><p>In ~5 mins: what dot-skill actually generates, the capability/persona split, the S = (A, M, L) contract, the correct-and-roll-back loop, the behavioral-fidelity gap the paper admits, and a full install-to-rollback walkthrough at the end.</p></blockquote><p>A tool that turns your coworker into an installable AI skill crossed roughly 18,500 GitHub stars.</p><p>dot-skill reads a person&#39;s scattered work traces, their docs, code reviews, and chat decisions, and writes them into a skill file an agent can load.</p><p>The backlash arrived fast. Someone shipped an anti-distillation skill that adds noise to your own traces so you cannot be cleanly copied.</p><p>Now there is a paper. COLLEAGUE.SKILL, from Shanghai AI Lab, 29 May, drops the digital-twin pitch for a narrower claim: this is a file format for expertise, not a copy of a person.</p><p>The useful part is the artifact. Whether it keeps the judgment is the part nobody has measured.</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>dot-skill is open source under MIT, written in Python, at titanwings/colleague-skill. It started as colleague.skill, built for one job: when a teammate quits, capture their review standards and incident heuristics before the context walks out with them.</p><p>The five-person team at Shanghai AI Lab posted the technical report to arXiv on May 29, 2026. MIT Technology Review had already covered the trend in April, and the &quot;distill them before they leave&quot; framing is what drew both the stars and the pushback.</p><p>[圖 1]</p><p>It builds on the Agent Skills standard, where a skill is a folder around a SKILL.md file plus optional scripts and references, loaded on demand. The repo ships three presets: colleague (the main one), celebrity, and relationship. A public gallery lists 215 skills from 165 contributors, which measures distribution, not whether any of them work.</p><hr><h2 id="what-it-actually-generates" tabindex="-1">What it actually generates <a class="header-anchor" href="#what-it-actually-generates" aria-label="Permalink to &quot;What it actually generates&quot;">​</a></h2><p>Expertise rarely lives in a manual. It is scattered across design docs, review comments, chat decisions, and incident notes.</p><p>dot-skill reads those traces and writes a few plain Markdown files. The loadable one is SKILL.md. Behind it sit work.md (what the person knows) and persona.md (how they act).</p><p>Because it follows the Agent Skills format, any compatible host loads it: Claude Code, OpenClaw, Codex, or Hermes. And because the output is Markdown, you can read the extracted rules, fix them in plain English, version the result, and roll it back.</p><hr><h2 id="the-design" tabindex="-1">The design <a class="header-anchor" href="#the-design" aria-label="Permalink to &quot;The design&quot;">​</a></h2><p>[圖 2]</p><p><strong>reframe</strong></p><p>The paper calls the method person-grounded trace-to-skill distillation. A lightweight profile, a source scope, and a set of documents map to a package the paper writes as S = (A, M, L): the generated files, the install metadata, and the lifecycle state (version, correction count, rollback history). The package is meant to be portable, inspectable, composable, correctable, and governable.</p><p><strong>split</strong></p><p>The sharpest design choice is keeping capability separate from behavior. work.md holds review criteria, workflows, and decision heuristics. persona.md holds tone, interaction rules, and a correction log.</p><p>Those generate three entry points: the full skill, work-only, and persona-only. Work-only is the safer one, because a review checklist does not need a personality. In the paper&#39;s example, a colleague skill encodes a review order: check authentication, input validation, rate limiting, response schema, and sensitive-data exposure before smaller issues.</p><p><strong>files</strong></p><p>Generation emits seven files on schema v3: SKILL.md, work.md, persona.md, the two sub-skills work_skill.md and persona_skill.md, plus manifest.json and meta.json for install and lifecycle metadata.</p><p><strong>fix loop</strong></p><p>Corrections are plain language. Say &quot;he would not push back there&quot; and the handler routes it: a work correction patches the matching ## section in work.md, a behavior correction appends a {scene, wrong, correct} record to persona.md. Every update archives the prior version first, and version_manager.py rolls back to any of the last 10.</p><p><strong>The honest part</strong></p><p>The paper makes one kind of claim: that this format and workflow exist and run. It does not claim the skill reproduces the person or improves anyone&#39;s work. The authors name their own open problem the behavioral fidelity frontier, and the paper ships no held-out task study to close it.</p><hr><h2 id="how-to-get-started" tabindex="-1">How to get started <a class="header-anchor" href="#how-to-get-started" aria-label="Permalink to &quot;How to get started&quot;">​</a></h2><p>Here is the short path. Every command, including install-to-deploy and rollback, is in the appendix at the end.</p><p>Clone the repo into your host&#39;s skills directory, or hand the URL to your agent and let it install itself. Then run /dot-skill, pick the colleague family, and answer three questions: an alias, a one-line role, and a few personality tags.</p><p>Point it at authorized traces. It can auto-collect from Feishu, DingTalk, or Slack, or take uploads: PDFs, screenshots, .eml files, or pasted text. It then generates the files and, by default, installs the skill into Claude Code.</p><p>Read work.md before you trust it. Then invoke the full skill with /{character}-{slug}, or the safer work-only path with /{character}-{slug}-work. Full install-to-rollback commands are in the appendix below.</p><hr><h2 id="alphasignal-take" tabindex="-1">AlphaSignal Take <a class="header-anchor" href="#alphasignal-take" aria-label="Permalink to &quot;AlphaSignal Take&quot;">​</a></h2><p>dot-skill ships real software: collectors, a writer, installers, rollback, and 35 passing tests. The gap is between what the product page sells and what the paper will actually claim.</p><p><strong>No fidelity evidence.</strong></p><p>The paper proves a file format, not that a generated skill catches what the real engineer would. It says so itself and ships no held-out evaluation. You are trusting extraction quality you cannot yet measure.</p><p><strong>The persona layer can turn a label into a rule.</strong></p><p>The colleague persona analyzer translates freeform tags like &quot;blame-shifter&quot; or &quot;PUA&quot; into Layer 0 rules the agent must never break, and manual tags outrank the actual traces. The repo&#39;s own colleague demo shows the skill dodging blame on cue. That is bias compiled into behavior, by design.</p><p><strong>Governance is an affordance, not a guarantee.</strong></p><p>Local-first, versioned files give you control, but nothing enforces consent, retention, or redaction in code, and deletion is rm -rf. The product site mentions RAG, yet there is no retrieval runtime in the repo (requirements.txt is requests, pypinyin, playwright, slack-sdk, python-docx, and openpyxl).</p><p>So the best recommendation is to adopt the work-only path and treat the rest as a research preview. Package a departing engineer&#39;s review checklist as a work.md skill, test it against reviews you already graded, and keep persona off until someone measures fidelity. Separate relationship and celebrity papers are promised, which is exactly where the consent questions get harder.</p><hr><p>If a teammate left tomorrow, would you trust a work-only skill of their review checklist, or is judgment the part that never compiles?</p><p>All source links are in the first reply. Full breakdown of recent updates + daily signals in our newsletter (link in bio).</p><hr><h2 id="appendix-how-to-actually-run-dot-skill" tabindex="-1">Appendix: How to actually run dot-skill <a class="header-anchor" href="#appendix-how-to-actually-run-dot-skill" aria-label="Permalink to &quot;Appendix: How to actually run dot-skill&quot;">​</a></h2><p>[圖 3]</p><p>Shorter than the repo&#39;s README. Eight steps, install to rollback.</p><p><strong>1. Install dot-skill into your host.</strong></p><p>Clone the repo into your host&#39;s skills directory. For Claude Code that is ~/.claude/skills/dot-skill.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/titanwings/colleague-skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills/dot-skill</span></span></code></pre></div><p>OpenClaw uses ~/.openclaw/workspace/skills/dot-skill, Codex uses ~/.codex/skills/dot-skill. For Hermes, clone anywhere and run python3 tools/install_hermes_skill.py --force. Or skip all of this and tell your agent to install the skill at the repo URL.</p><p><strong>2. Launch and pick a family.</strong></p><p>Run /dot-skill and choose colleague. The other presets are relationship and celebrity.</p><p><strong>3. Answer the intake.</strong></p><p>Three questions: alias, a one-line role, and personality tags. Keep the tags factual. They become behavior rules, not flavor text.</p><p><strong>4. Provide source material.</strong></p><p>Auto-collect from a chat platform, or upload files.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Slack auto-collect (an admin installs the bot; free workspaces cap history at 90 days)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/slack_auto_collector.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/slack_auto_collector.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Jane Doe&quot;</span></span></code></pre></div><p>Or upload PDFs, screenshots, .eml archives, or pasted text. You can also skip collection and generate from the intake alone.</p><p><strong>5. Generate and inspect.</strong></p><p>Generation runs through the writer and emits all seven files.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/skill_writer.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --character</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> colleague</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --slug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jane-doe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Jane Doe&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --meta</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/meta.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --work</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/work.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --persona</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/persona.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./skills/colleague</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --no-install-claude-skill</span></span></code></pre></div><p>By default the create step auto-installs into Claude Code. Pass --no-install-claude-skill to stop and read work.md and persona.md first. This is where you catch a manual tag that became a rule it should not have.</p><p><strong>6. Install the generated skill to a host.</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/install_claude_generated_skill.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills/colleague/jane-doe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>Use install_openclaw_generated_skill.py or install_codex_generated_skill.py for the other hosts. Then invoke the full skill with /colleague-jane-doe, or the work-only entry point with /colleague-jane-doe-work.</p><p><strong>7. Correct it in plain English.</strong></p><p>Tell the agent what is wrong. A work fix patches a ## section, a behavior fix becomes a {scene, wrong, correct} record.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/skill_writer.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --character</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> colleague</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --slug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jane-doe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --correction-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/correction.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./skills/colleague</span></span></code></pre></div><p><strong>8. Version and roll back.</strong></p><p>Every update archives the prior version. The version manager keeps the last 10, and cleanup is manual, so old versions stay until you remove them.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/version_manager.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --character</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> colleague</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --slug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jane-doe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./skills/colleague</span></span></code></pre></div><p>Deploy maps to wherever your agent reads skills: ~/.claude/skills/, ~/.codex/skills/, or the Hermes skill directory.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：dot-skill 將離職工程師的 review 標準與決策啟發提取為可版控的 Markdown skill 文件，capability/persona 分離設計是亮點，但 behavioral fidelity 未被測量。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>工作痕跡→skill file</strong>：讀取 code review、chat 決策、incident notes，生成 SKILL.md + work.md + persona.md 三層結構</li><li><strong>S = (A, M, L) 設計</strong>：文件包（artifacts）+ 安裝元數據（metadata）+ 生命週期狀態（lifecycle）</li><li><strong>capability/persona 分離</strong>：work.md（能力）vs persona.md（行為），work-only 入口點是更安全的生產路徑</li><li><strong>Plain English 修正 + 回滾</strong>：修正自動路由到對應文件；version_manager.py 保留最後 10 版</li><li><strong>AlphaSignal 建議</strong>：採用 work-only 路徑，用你已評分的 review 測試品質，persona 等 fidelity 研究發表後再啟用</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>GitHub stars: ~18,500（titanwings/colleague-skill，MIT）</li><li>Skills gallery: 215 skills / 165 contributors</li><li>生成 7 個文件：SKILL.md, work.md, persona.md, work_skill.md, persona_skill.md, manifest.json, meta.json</li><li>版本管理：保留最後 10 版，manual cleanup</li><li>35 passing tests</li><li>論文：Shanghai AI Lab, arXiv, 2026-05-29</li><li>相容 host：Claude Code / OpenClaw / Codex / Hermes</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>Fidelity gap</strong>：論文本身承認沒有 held-out task study，只證明 format 機制存在，不能證明 skill 能重現工程師的判斷品質</li><li><strong>Persona 偏見風險</strong>：freeform 人格標籤（如「blame-shifter」）直接編譯成 Layer 0 規則，manual tags 優先於實際 traces，等於把主觀偏見硬編碼進行為</li><li><strong>治理是能力非保證</strong>：local-first + versioned 提供控制能力，但代碼層面沒有 consent / redaction / retention 執行機制，刪除 = <code>rm -rf</code></li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>work-only 路徑可直接套用至 .claude/skills/，但需先測試提取品質</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>工作痕跡→可版控 skill 的格式化框架，capability/persona 分離設計有新意</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>有 35 tests 但無 fidelity evaluation，論文只證明 format 存在</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>S=(A,M,L) 架構、7 文件生成、修正路由、版本管理全部覆蓋，附完整 CLI</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>設計上相容多個 Agent Skills host，但主要場景是工程師離職知識傳承</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.0/10</strong></td><td>7×0.3+8×0.2+5×0.2+8×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：直接涉及 .claude/skills/ 設計哲學，work-only 提取流程可強化現有 skill 文件的結構設計（特別是 work.md 的 review checklist 模式）。</p>`,99)])])}const g=a(l,[["render",n]]);export{c as __pageData,g as default};
